import{a as e,n as t}from"./rolldown-runtime-Cyuzqnbw.js";import{O as n,a as r,k as i,p as a,s as o,t as s,x as c}from"./framer-DPWtvxwd.js";import{h as l}from"./react-vendor-B45kknb5.js";import{M as u,S as d,X as f,cn as p,fn as m,in as h,m as g,nt as _,t as v,v as y,vn as b}from"./icons-CARiYJLk.js";var x,S=t((()=>{v(),x=[{slug:`voiture-immobilisee-defaut-assurance`,titre:`Voiture immobilisée pour défaut d'assurance : comment la récupérer`,extrait:`Véhicule immobilisé ou en fourrière pour défaut d'assurance ? Assurez-vous en 5 minutes, attestation immédiate, et récupérez votre voiture légalement.`,reponseRapide:`Pour obtenir la mainlevée et récupérer un véhicule immobilisé, vous devez présenter une attestation d'assurance valide et votre permis de conduire. Une assurance temporaire, dès 1 jour, suffit et délivre une attestation immédiate.`,icone:d,accent:`#B05C3A`,categorie:`Urgence`,readTime:`4 min`,hasPage:!0},{slug:`controle-sans-assurance-risques-amende`,titre:`Contrôlé sans assurance : risques, amende et que faire`,extrait:`Amende de 500 € à 3 750 €, immobilisation possible, peines complémentaires… Les vrais risques du défaut d'assurance et comment se mettre en règle en 5 minutes.`,reponseRapide:`Rouler sans assurance est un délit (article L324-2 du Code de la route), pas une simple contravention : il expose à une forte amende et à des peines complémentaires comme la suspension du permis. Une assurance temporaire souscrite en ligne vous remet en règle immédiatement, attestation à l'appui.`,icone:d,accent:`#B05C3A`,categorie:`Urgence`,readTime:`4 min`,hasPage:!0,featured:!1},{slug:`combien-de-jours-assurance-sortir-fourriere`,titre:`Sortie de fourrière : combien de jours d'assurance faut-il souscrire ?`,extrait:`Combien de jours d'assurance pour sortir une voiture de la fourrière ? La fiche d'immobilisation fixe le minimum. Attestation immédiate en ligne, dès 1 jour.`,reponseRapide:`Aucune durée minimale n'est imposée : il suffit de présenter une attestation d'assurance valide le jour de la récupération. Une formule temporaire dès 1 jour permet de ressortir le véhicule légalement.`,icone:u,accent:`#B05C3A`,categorie:`Urgence`,readTime:`4 min`,hasPage:!0},{slug:`assurer-vehicule-achete-chez-particulier`,titre:`Assurer un véhicule acheté chez un particulier`,extrait:`Vous venez d'acheter un véhicule entre particuliers ? Voici comment rouler assuré dès le premier trajet, sans attendre la carte grise.`,reponseRapide:`Assurez le véhicule à votre nom dès l'achat : le contrat du vendeur est suspendu dès le lendemain et un accident retomberait sur son bonus. Une assurance temporaire vous couvre le jour même, sans attendre la carte grise.`,icone:h,accent:`#C98A3C`,categorie:`Achat véhicule`,readTime:`5 min`,hasPage:!0},{slug:`assurance-temporaire-vehicule-etranger-france`,titre:`Véhicule ou permis étranger : assurance temporaire en France`,extrait:`Véhicule à plaque étrangère ou retour de l'étranger ? Roulez assuré en France le temps de l'immatriculer. Attestation immédiate, 1 à 90 jours.`,reponseRapide:`Un véhicule immatriculé à l'étranger ou conduit avec un permis étranger peut être assuré en France de façon temporaire. La responsabilité civile est couverte dès le premier jour, avec une carte internationale d'assurance valable dans 34 pays.`,icone:p,accent:`#5E7CA8`,categorie:`International`,readTime:`5 min`,hasPage:!0},{slug:`assurance-temporaire-pret-de-vehicule`,titre:`Prêter ou emprunter un véhicule en toute sécurité`,extrait:`Un ami vous prête sa voiture ou vous lui prêtez la vôtre ? L'assurance temporaire protège le conducteur désigné sans toucher au bonus-malus du propriétaire.`,reponseRapide:`Prêter son véhicule est possible, mais selon le contrat un accident causé par l'emprunteur peut entraîner une franchise prêt de volant et affecter le bonus du propriétaire. Une assurance temporaire au nom de l'emprunteur couvre la durée du prêt et protège le contrat du propriétaire.`,icone:g,accent:`#7E9B79`,categorie:`Prêt de véhicule`,hasPage:!0},{slug:`assurance-temporaire-convoyage-professionnel`,titre:`Convoyage professionnel : quelle assurance ?`,extrait:`Mandataires, négociants, transporteurs : assurez chaque véhicule convoyé (roulant) pour la durée exacte du trajet, sans contrat annuel inutile.`,icone:y,accent:`#B0703F`,categorie:`Pro & convoyage`,hasPage:!0},{slug:`assurance-temporaire-rouler-en-attendant-carte-grise`,titre:`Rouler en attendant sa carte grise définitive`,extrait:`Les délais de carte grise s'étirent ? Le CPI vous autorise à rouler 1 mois en France. Couvrez-vous pendant la période de transition avec une attestation immédiate, valable dès la souscription.`,icone:b,accent:`#C9A84C`,categorie:`Carte grise`,readTime:`4 min`,hasPage:!0},{slug:`assurance-temporaire-essai-vehicule-avant-achat`,titre:`Essayer un véhicule avant achat, bien assuré`,extrait:`En concession vous êtes souvent couvert, chez un particulier c'est plus risqué. Une assurance d'un jour sécurise l'essai sans toucher au contrat du vendeur.`,icone:m,accent:`#8A6B9E`,categorie:`Essai & achat`,hasPage:!0},{slug:`assurance-temporaire-resilie-par-assureur`,titre:`Résilié par votre assureur : quelles solutions ?`,extrait:`Résilié pour impayé, sinistres ou fausse déclaration ? Selon le motif, une assurance temporaire vous remet en règle en 5 minutes, le temps de retrouver un contrat annuel.`,reponseRapide:`La responsabilité civile reste obligatoire (article L211-1). Résilié pour impayé ou non-renouvellement, une assurance temporaire peut vous couvrir immédiatement ; résilié pour sinistre, la solution passe par un assureur spécialisé ou le Bureau central de tarification.`,icone:f,accent:`#C2705A`,categorie:`Résiliation`,readTime:`5 min`,hasPage:!0},{slug:`assurance-temporaire-utilitaire-demenagement`,titre:`Déménager avec un utilitaire : bien assuré à la journée`,extrait:`Utilitaire loué, prêté ou tout juste acheté ? Assurez-le pour la durée exacte du déménagement, attestation immédiate, responsabilité civile incluse. 1 à 90 jours.`,reponseRapide:`Un utilitaire doit être assuré au minimum en responsabilité civile, même pour un aller-retour. En location, l'assurance est souvent incluse ; pour un utilitaire prêté ou acheté, une assurance temporaire à votre nom vous couvre pour la durée du déménagement.`,icone:y,accent:`#6E92A8`,categorie:`Utilitaire`,readTime:`5 min`,hasPage:!0},{slug:`assurance-temporaire-vehicule-proche-decede`,titre:`Assurer la voiture d'un proche décédé`,extrait:`Au décès, le contrat auto se transmet aux héritiers mais ne vous couvre pas toujours. Une assurance temporaire vous permet de déplacer ou vendre le véhicule, attestation immédiate.`,reponseRapide:`Au décès, le contrat se transmet de plein droit aux héritiers (article L121-10), mais l'héritier qui conduit n'est pas toujours couvert. Une assurance temporaire à votre nom vous couvre immédiatement pour déplacer ou vendre le véhicule, sans dépendre du contrat du défunt.`,icone:_,accent:`#8E86A6`,categorie:`Succession`,readTime:`5 min`,hasPage:!0}]}));function C(){let e=(0,w.useSyncExternalStore)(D,O,k),t=r(),{scrollYProgress:n}=a(),i=o(n,{stiffness:140,damping:30,restDelta:.001});return!e||typeof document>`u`?null:(0,T.createPortal)((0,E.jsx)(c.div,{"aria-hidden":`true`,style:{position:`fixed`,top:0,left:0,right:0,height:2,transformOrigin:`0% 50%`,scaleX:t?n:i,background:`linear-gradient(90deg, #C9A84C, #E8C97A)`,zIndex:120,pointerEvents:`none`}}),document.body)}var w,T,E,D,O,k,A=t((()=>{w=e(i()),T=e(l()),s(),E=n(),D=()=>()=>{},O=()=>!0,k=()=>!1}));export{S as i,A as n,x as r,C as t};